[[ ## response ## ]]
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(data[j], data[j + 1]):
                    self.swap(data, j, j + 1)
        return data

    @abstractmethod
    def compare(self, a, b):
        pass

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

class SelectionSort(SortAlgorithm):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(data[min_idx], data[j]):
                    min_idx = j
            self.swap(data, i, min_idx)
        return data

    def compare(self, a, b):
        return a > b

# Testing
arr1 = [64, 34, 25, 12, 22, 11, 90]
bubble = BubbleSort()
print(f"Bubble Sort: {bubble.sort(arr1)}")

arr2 = ["banana", "apple", "cherry"]
selection = SelectionSort()
print(f"Selection Sort: {selection.sort(arr2)}")

