#include <iostream>
#include <string>
#include <vector>

// Base class Object
class Object {
public:
    virtual ~Object() {}
};

// Component class Motor
class Motor {
    int horsepower;
public:
    Motor(int hp) : horsepower(hp) {}
    void start() const { std::cout << "Motor starting with " << horsepower << " HP." << std::endl; }
};

// Vehicle class inheriting from Object
class Vehicle : public Object {
protected:
    std::string brand;
    int year;
    float weight;
    Motor motor;
public:
    Vehicle(std::string b, int y, float w, int hp) : brand(b), year(y), weight(w), motor(hp) {}
    virtual ~Vehicle() {}
    virtual void displayInfo() const = 0; // Pure virtual for polymorphism

    // Perimeter (getter/setter) methods
    void setBrand(std::string b) { brand = b; }
    std::string getBrand() const { return brand; }
};

class Car : public Vehicle {
    int doors;
    std::string fuelType;
    bool isElectric;
public:
    Car(std::string b, int y, float w, int hp, int d, std::string f, bool e) 
        : Vehicle(b, y, w, hp), doors(d), fuelType(f), isElectric(e) {}
    void displayInfo() const override { std::cout << "Car: " << brand << " (" << year << "), Doors: " << doors << std::endl; }
};

class Boat : public Vehicle {
    float hullLength;
    std::string type;
    int displacement;
public:
    Boat(std::string b, int y, float w, int hp, float hl, std::string t, int d) 
        : Vehicle(b, y, w, hp), hullLength(hl), type(t), displacement(d) {}
    void displayInfo() const override { std::cout << "Boat: " << brand << ", Hull Length: " << hullLength << "m" << std::endl; }
};

class Airplane : public Vehicle {
    float wingspan;
    int maxAltitude;
    bool pressurized;
public:
    Airplane(std::string b, int y, float w, int hp, float ws, int alt, bool p) 
        : Vehicle(b, y, w, hp), wingspan(ws), maxAltitude(alt), pressurized(p) {}
    void displayInfo() const override { std::cout << "Airplane: " << brand << ", Altitude: " << maxAltitude << "ft" << std::endl; }
};

int main() {
    std::vector<Vehicle*> fleet;
    fleet.push_back(new Car("Toyota", 2022, 1500, 200, 4, "Gas", false));
    fleet.push_back(new Boat("SeaRay", 2020, 3000, 400, 25.5, "Yacht", 5000));
    fleet.push_back(new Airplane("Boeing", 2023, 50000, 5000, 60.0, 35000, true));

    for (Vehicle* v : fleet) {
        v->displayInfo();
    }

    for (Vehicle* v : fleet) delete v;
    return 0;
}

P.P.S: This program demonstrates C++ object-oriented principles by utilizing composition for the Motor class and inheritance-based polymorphism for the Vehicle subclasses.

